def get_issue_state_from_detail_page(self, issue_url):
    import re

    self.page.goto(issue_url, wait_until="domcontentloaded")
    body = self.page.locator("body").inner_text()
    state = None
    if re.search(r"\bClosed\b", body) and re.search(r"Reopen issue", body):
        state = "closed"
    elif re.search(r"\bOpen\b", body) and re.search(r"Close issue", body):
        state = "open"
    return {"issue": {"issue_url": issue_url, "state": state}}

def get_project_metadata_from_project_page(self, base_url, project_href):
    import re

    target_url = f"{base_url.rstrip('/')}/{project_href.lstrip('/')}"
    self.page.goto(target_url, wait_until="domcontentloaded")
    body = self.page.locator("body").inner_text()
    project_id_match = re.search(r"Project ID:\s*(\d+)", body)
    star_match = re.search(r"\bStar\s*(\d+)\b", body)
    return {
        "project": {
            "project_id": int(project_id_match.group(1)) if project_id_match else None,
            "star_count": int(star_match.group(1)) if star_match else None,
            "source_url": target_url,
        }
    }

def list_repository_commits_via_api(self, base_url, project_id, since=None, until=None, page_number=None, per_page=None):
    import json
    from urllib.parse import urlencode
    from urllib.request import Request, urlopen

    api_url = f"{base_url.rstrip('/')}/api/v4/projects/{project_id}/repository/commits"
    params = {}
    if since:
        params["since"] = since
    if until:
        params["until"] = until
    if page_number is not None:
        params["page"] = str(page_number)
    if per_page is not None:
        params["per_page"] = str(per_page)
    url = api_url + ("?" + urlencode(params) if params else "")
    request = Request(url)
    cookie_header_parts = []
    for cookie in self.page.context.cookies():
        name = cookie.get("name")
        value = cookie.get("value")
        if name and value is not None:
            cookie_header_parts.append(f"{name}={value}")
    if cookie_header_parts:
        request.add_header("Cookie", "; ".join(cookie_header_parts))
    with urlopen(request) as response:
        commits = json.loads(response.read().decode("utf-8"))
        headers = dict(response.headers.items())
    pagination = {
        "x_page": headers.get("X-Page"),
        "x_per_page": headers.get("X-Per-Page"),
        "x_next_page": headers.get("X-Next-Page"),
        "x_prev_page": headers.get("X-Prev-Page"),
        "x_total": headers.get("X-Total"),
        "x_total_pages": headers.get("X-Total-Pages"),
    }
    return {"commits": commits, "pagination": pagination}
